// Helper function to count the number of notes in the music_string
function CountNotes(music_string: string): int
    requires music_string != null
    ensures CountNotes(music_string) >= 0
{
    // This function counts the occurrences of 'o', 'o|', and '.|' in music_string
    var count := 0;
    var i := 0;
    while i < music_string.Length
        invariant 0 <= i <= music_string.Length
        invariant count >= 0
    {
        if music_string[i] == 'o' {
            count := count + 4;
            i := i + 1;
        } else if i + 1 < music_string.Length && music_string[i] == 'o' && music_string[i + 1] == '|' {
            count := count + 2;
            i := i + 2;
        } else if i + 1 < music_string.Length && music_string[i] == '.' && music_string[i + 1] == '|' {
            count := count + 1;
            i := i + 2;
        } else {
            i := i + 1; // Move to the next character
        }
    }
    return count;
}
